            failures++;
        }
    }

    public static void main(String[] args) {
        EpisodeFeed empty = new EpisodeFeed();
        check("empty feed has no longest episode", null, empty.longest());

        EpisodeFeed feed = new EpisodeFeed();
        feed.add(new Episode("Morning Wrap", "Daily Brief", 12));
        feed.add(new Episode("Deep Dive", "Tech Hour", 62));
        feed.add(new Episode("Evening Wrap", "Daily Brief", 14));
        feed.add(new Episode("Long Read", "Tech Hour", 62));
        feed.add(null);

        check("null episodes are ignored", 4, feed.size());
        check("totalMinutes", 150, feed.totalMinutes());
        check("minutesFor ignores case", 26, feed.minutesFor("daily brief"));
        check("minutesFor an unknown show", 0, feed.minutesFor("Ghost Stories"));
        check("shows sorted A-Z", "[Daily Brief, Tech Hour]", feed.shows().toString());
        check("longest wins ties by insertion order", new Episode("Deep Dive", "Tech Hour", 62), feed.longest());
        check("averageMinutes", 37.5, feed.averageMinutes());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
