import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * TASK: Complete EpisodeFeed. The Episode record above it is provided
 * and already works -- do not change it.
 *
 * A feed HAS a list of Episodes (composition) and answers aggregate
 * questions about them. It must not extend a collection class.
 *
 * Rules:
 *   - add(episode) ignores null
 *   - totalMinutes() adds up every episode length (0 for an empty feed)
 *   - minutesFor(show) sums only that show's episodes, comparing the show
 *     name IGNORING CASE (0 when the show is unknown)
 *   - shows() returns the distinct show names as first spelled, sorted A-Z
 *   - longest() returns the episode with the most minutes, or null when the
 *     feed is empty; on a tie the FIRST one added wins
 *   - averageMinutes() returns totalMinutes / episode count as a double,
 *     and exactly 0.0 when the feed is empty
 *
 * Example: a feed of 25-minute and 62-minute episodes has totalMinutes() 87,
 *   averageMinutes() 43.5 and longest().title() "Deep Dive".
 */
record Episode(String title, String show, int minutes) {
}

public class EpisodeFeed {

    private final List<Episode> episodes = new ArrayList<>();

    public void add(Episode episode) {
        if (episode == null) {
            return;
        }
        episodes.add(episode);
    }

    public int size() {
        return episodes.size();
    }

    public int totalMinutes() {
        int total = 0;
        for (Episode episode : episodes) {
            total = total + episode.minutes();
        }
        return total;
    }

    public int minutesFor(String show) {
        if (show == null) {
            return 0;
        }
        int total = 0;
        for (Episode episode : episodes) {
            if (episode.show().equalsIgnoreCase(show)) {
                total = total + episode.minutes();
            }
        }
        return total;
    }

    public List<String> shows() {
        List<String> names = new ArrayList<>();
        for (Episode episode : episodes) {
            if (!names.contains(episode.show())) {
                names.add(episode.show());
            }
        }
        Collections.sort(names);
        return names;
    }

    public Episode longest() {
        Episode best = null;
        for (Episode episode : episodes) {
            if (best == null || episode.minutes() > best.minutes()) {
                best = episode;
            }
        }
        return best;
    }

    public double averageMinutes() {
        if (episodes.isEmpty()) {
            return 0.0;
        }
        return (double) totalMinutes() / episodes.size();
    }
}
